#!/bin/bash
sed -i '/const handleCreateSubmit = async (e: React.FormEvent) => {/i \ \ const handleDelete = async (id: string) => {\n    if (!window.confirm(language === "bn" ? "আপনি কি নিশ্চিত যে এটি মুছে ফেলতে চান?" : "Are you sure you want to delete this proposal?")) return;\n    try {\n      const res = await apiFetch(`/api/postfactoproposals/${id}`, { method: "DELETE" });\n      const data = await res.json();\n      if (data.error) throw new Error(data.error);\n      fetchProposals();\n    } catch (err: any) {\n      alert(err.message);\n    }\n  };\n' src/components/PostFactoProposalsView.tsx
sed -i 's/<Edit2 className="w-4 h-4" \/>\n                              <\/button>/<Edit2 className="w-4 h-4" \/>\n                              <\/button>\n                              <button onClick={() => handleDelete(p.id)} className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg"><Trash2 className="w-4 h-4" \/><\/button>/' src/components/PostFactoProposalsView.tsx
